pair A, B, C, D, E, F, M,N,P,Q;
A=(0,0);
B=(12,0);
C=(6,-6);
D=(6,-22);
E=(0,-16);
F=(12,-16);
M=(2D+E)/3;
N=(5D+F)/6;
P=(2C+B)/3;
Q=(2A+C)/3;

draw(A--B--C--A--E--D--F--B--C--D);
draw(M--N--P--Q--M, dashed);
label("$A$", A, NW);
label("$B$", B, NE);
label("$C$", C, dir(90));
label("$D$", D, S);
label("$E$", E, SW);
label("$F$", F, SE);
label("$M$", M, SW);
label("$N$", N, SE);
label("$P$", P, SE);
label("$Q$", Q, W);
label("12", (A+B)/2, dir(90));
label("16", (B+F)/2, dir(0));
[/asy]
